# [SAME-SCENARIO] answer_with_context.py\nimport os\nfrom model_client import get_llm_client\nfrom model_models import PromptRequest, normalize_response\n\ndef answer_with_context(question: str, context: str) -> str:\n    """Answer a question using provided context with a hosted LLM.\n    Uses the provider configured in environment variables."""\n    client = get_llm_client()\n    prompt = f\"You are an AI assistant.\nContext: {context}\\nQuestion: {question}\\nAnswer in three sentences:\"\n    request = PromptRequest(\n        messages=[{\"role\": \"user\", \"content\": prompt}],\n        model=\"gpt-4o-mini\",  # Model identifier for the selected provider\n    )\n    response = client.chat_completions(request)\n    result = normalize_response(response)\n    return result[\"choices\"][0][\"message\"][\"content\"].strip()\n